 function updateView(){svg.setAttribute('viewBox',`${graphView.x} ${graphView.y} ${graphView.w} ${graphView.h}`);graphZoom=1000/graphView.w;const z=$('#zoomLabel');if(z)z.textContent=`${Math.round(graphZoom*100)}%`}
 function paint(){const byId=Object.fromEntries(graph.nodes.map(n=>[n.id,n]));const edgeMarkup=graph.edges.map((e,i)=>{const a=byId[e.from],b=byId[e.to];if(!a||!b)return '';const acx=a.x+114,acy=a.y+39,bcx=b.x+114,bcy=b.y+39,dx=bcx-acx,dy=bcy-acy,len=Math.max(1,Math.hypot(dx,dy)),scale=Math.min(114/Math.max(Math.abs(dx),.001),39/Math.max(Math.abs(dy),.001)),sx=acx+dx*scale,sy=acy+dy*scale,ex=bcx-dx*scale,ey=bcy-dy*scale,mx=(sx+ex)/2,my=(sy+ey)/2,bend=((i%3)-1)*25,cx=mx-(dy/len)*bend,cy=my+(dx/len)*bend,lx=(sx+2*cx+ex)/4,ly=(sy+2*cy+ey)/4,dir=e.direction||'forward',dash=e.confidence==='unverified'?'stroke-dasharray="5 5"':'';return `<g class="graph-edge-group ${selectedEdge===i?'edge-selected':''}" data-edge="${i}" tabindex="0" role="button" aria-label="${esc(e.label)} ${esc(dirs[dir]||'→')}"><path class="graph-edge ${e.confidence==='unverified'?'unverified':''}" d="M ${sx} ${sy} Q ${cx} ${cy} ${ex} ${ey}" ${dash} ${dir==='none'?'':'marker-end="url(#atlas-arrow)"'} ${dir==='both'?'marker-start="url(#atlas-arrow)"':''}/><rect class="edge-label-bg" x="${lx-68}" y="${ly-13}" width="136" height="26" rx="13"/><text class="edge-label" x="${lx}" y="${ly+4}">${esc(e.label)} ${dirs[dir]||'→'}</text></g>`}).join('');const nodeMarkup=graph.nodes.map(n=>{const col=colors[n.type]||prefs.accent;return `<g class="graph-node ${n.id===selectedNode||n.id===graphFrom?'selected':''}" style="--node-color:${col}" data-node="${esc(n.id)}" transform="translate(${n.x},${n.y})" tabindex="0" role="button" aria-label="${esc(n.name)} — ${esc(types[n.type]||t('other'))}"><rect class="node-body" width="228" height="78" rx="39"/><circle class="node-halo" cx="39" cy="39" r="25"/><circle class="node-point" cx="39" cy="39" r="8"/><text x="77" y="34">${esc(n.name.length>23?n.name.slice(0,22)+'…':n.name)}</text><text class="kind" x="77" y="55">${esc(types[n.type]||t('other'))}${n.value?` · ${esc(n.value.length>18?n.value.slice(0,17)+'…':n.value)}`:''}</text></g>`}).join('');svg.innerHTML=`<defs><marker id="atlas-arrow" viewBox="0 0 12 10" refX="12" refY="5" markerWidth="10" markerHeight="9" orient="auto-start-reverse" markerUnits="userSpaceOnUse"><path d="M 0 0 L 12 5 L 0 10 z" fill="var(--accent)"/></marker></defs>${edgeMarkup}${nodeMarkup}`;updateView()}
 function inspector(){const host=$('#graphInspector');if(selectedNode){const n=graph.nodes.find(z=>z.id===selectedNode);host.innerHTML=n?`<div class="inspector-title"><span class="inspector-dot" style="--entity:${colors[n.type]||prefs.accent}"></span><div><b>${t('nodeDetails')}</b><small>${esc(types[n.type]||t('other'))}</small></div></div><form id="editNode" class="inspector-fields"><label>${t('entityName')}<input id="inspectName" value="${esc(n.name)}" maxlength="80"></label><label>${t('type')}${typeSelect(n.type)}</label><label>${t('identifier')}<input id="inspectValue" value="${esc(n.value||'')}" placeholder="domain, email, username…"></label><label>${t('source')}<input id="inspectSource" value="${esc(n.source||'')}" placeholder="https://…"></label><label>${t('sourceDate')}<input id="inspectSourceDate" type="date" value="${esc(n.sourceDate||'')}"></label><label>${t('confidence')}<select id="inspectConfidence"><option value="unverified" ${(!n.confidence||n.confidence==='unverified')?'selected':''}>${t('unverified')}</option><option value="medium" ${n.confidence==='medium'?'selected':''}>${t('medium')}</option><option value="high" ${n.confidence==='high'?'selected':''}>${t('high')}</option></select></label><label>${t('notes')}<textarea id="inspectNotes" rows="3">${esc(n.notes||'')}</textarea></label><label>${t('relationship')}<input id="relationName" value="${prefs.lang==='ru'?'связан с':'associated with'}" maxlength="60"></label><label>${t('direction')}<select id="linkDirection"><option value="forward">→ ${t('forward')}</option><option value="both">↔ ${t('both')}</option><option value="none">— ${t('undirected')}</option></select></label><div class="inspector-actions"><button class="action primary">${t('saveChanges')}</button><button type="button" class="action" id="inspectorConnect">${graphConnect?t('cancelConnect'):t('connect')}</button><button type="button" class="action danger" id="inspectorDelete">${t('deleteNode')}</button></div></form><section class="pivot-section"><h3>${t('pivotTools')}</h3><p>${t('pivotHint')}</p>${pivotLinks(n).map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${ic('arrow-up-right')}</a>`).join('')}</section>`:`<div class="inspector-empty">${t('inspectorHint')}</div>`;const f=$('#editNode');if(f)f.onsubmit=e=>{e.preventDefault();checkpoint();n.name=$('#inspectName').value.trim()||n.name;n.type=$('#inspectType').value;n.value=$('#inspectValue').value.trim();n.source=$('#inspectSource').value.trim();n.sourceDate=$('#inspectSourceDate').value;n.confidence=$('#inspectConfidence').value;n.notes=$('#inspectNotes').value.trim();saveGraph();paint();inspector();updateStatus();toast(t('saved'))};const cb=$('#inspectorConnect');if(cb)cb.onclick=()=>{graphConnect=!graphConnect;graphFrom=graphConnect?selectedNode:null;graphPage()};const db=$('#inspectorDelete');if(db)db.onclick=()=>$('#deleteNode').click()}
 else if(selectedEdge!==null&&graph.edges[selectedEdge]){const ed=graph.edges[selectedEdge];host.innerHTML=`<div class="inspector-title">${ic('git-merge')}<div><b>${t('relationshipDetails')}</b><small>${esc(graph.nodes.find(n=>n.id===ed.from)?.name||'')} ${dirs[ed.direction||'forward']} ${esc(graph.nodes.find(n=>n.id===ed.to)?.name||'')}</small></div></div><form id="editEdge" class="inspector-fields"><label>${t('relationship')}<input id="inspectLabel" value="${esc(ed.label)}" maxlength="60"></label><label>${t('direction')}<select id="inspectDirection"><option value="forward" ${(!ed.direction||ed.direction==='forward')?'selected':''}>→ ${t('forward')}</option><option value="both" ${ed.direction==='both'?'selected':''}>↔ ${t('both')}</option><option value="none" ${ed.direction==='none'?'selected':''}>— ${t('undirected')}</option></select></label><label>${t('source')}<input id="inspectSource" value="${esc(ed.source||'')}" placeholder="https://…"></label><label>${t('sourceDate')}<input id="inspectSourceDate" type="date" value="${esc(ed.sourceDate||'')}"></label><label>${t('confidence')}<select id="inspectConfidence"><option value="unverified" ${(!ed.confidence||ed.confidence==='unverified')?'selected':''}>${t('unverified')}</option><option value="medium" ${ed.confidence==='medium'?'selected':''}>${t('medium')}</option><option value="high" ${ed.confidence==='high'?'selected':''}>${t('high')}</option></select></label><label>${t('notes')}<textarea id="inspectNotes" rows="3">${esc(ed.notes||'')}</textarea></label><div class="inspector-actions"><button class="action primary">${t('saveChanges')}</button><button class="action danger" type="button" id="removeEdge">${t('deleteRelationship')}</button></div></form>`;$('#editEdge').onsubmit=e=>{e.preventDefault();checkpoint();ed.label=$('#inspectLabel').value.trim()||ed.label;ed.direction=$('#inspectDirection').value;ed.source=$('#inspectSource').value.trim();ed.sourceDate=$('#inspectSourceDate').value;ed.confidence=$('#inspectConfidence').value;ed.notes=$('#inspectNotes').value.trim();saveGraph();paint();inspector();toast(t('saved'))};$('#removeEdge').onclick=()=>deleteEdge(selectedEdge)}
 else host.innerHTML=`<div class="inspector-empty">${ic('mouse-pointer-2')}<b>${t('inspectorHint')}</b><p>${t('inspectorHelp')}</p></div>`}
 function pivotLinks(n){const value=String(n.value||n.name||'').trim(),q=encodeURIComponent(value),exact=encodeURIComponent('"'+value+'"'),search=`https://www.google.com/search?q=${exact}`,duck=`https://duckduckgo.com/?q=${exact}`;let list=[['Google exact search',search]];if(n.type==='domain')list.push(['crt.sh certificates',`https://crt.sh/?q=${q}`],['VirusTotal domain',`https://www.virustotal.com/gui/domain/${q}`],['urlscan results',`https://urlscan.io/search/#domain%3D${q}`]);else if(n.type==='ip')list.push(['VirusTotal IP',`https://www.virustotal.com/gui/ip-address/${q}`],['ipinfo.io',`https://ipinfo.io/${q}`],['BGP.he.net',`https://bgp.he.net/ip/${q}`]);else if(n.type==='organization')list.push(['OpenCorporates',`https://opencorporates.com/companies?q=${q}`],['DuckDuckGo exact search',duck]);else if(n.type==='location')list.push(['Google Maps',`https://www.google.com/maps/search/${q}`],['DuckDuckGo exact search',duck]);else if(n.type==='account'||n.type==='other')list.push(['GitHub user search',`https://github.com/search?q=${q}&type=users`],['DuckDuckGo exact search',duck]);else list.push(['DuckDuckGo exact search',duck]);return list}
function confidenceLabel(v){return v==='high'?t('high'):v==='medium'?t('medium'):t('unverified')}function reportSafeLink(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function updateEmpty(){let e=wrap.querySelector('.graph-empty');if(!graph.nodes.length&&!e){e=document.createElement('div');e.className='graph-empty';const i=document.createElement('span');i.innerHTML=ic('share-2');const b=document.createElement('strong');b.textContent=t('graphEmpty');const hint=document.createElement('span');hint.textContent=t('graphEmptyHint');e.append(i,b,hint);wrap.append(e);drawIcons()}else if(graph.nodes.length&&e)e.remove()}
 function updateStatus(){updateEmpty();updateHistoryButtons();const h=$('#graphHint');if(h)h.textContent=graphConnect?(graphFrom?t('selectSecondNode'):t('selectNode')):selectedNode?`${t('selected')}: ${graph.nodes.find(n=>n.id===selectedNode)?.name||''}`:selectedEdge!==null?t('relationshipSelected'):t('graphHelp');const d=$('#deleteNode');if(d)d.disabled=!selectedNode;const c=$('#graphCounts');if(c)c.textContent=`${graph.nodes.length} ${t('nodes')} · ${graph.edges.length} ${t('edges')}`;const cm=$('#connectMode');if(cm)cm.classList.toggle('active',graphConnect)}
