 function addNode(type,name='',at=null){const count=graph.nodes.filter(n=>n.type===type).length+1,label=name.trim()||`${types[type]||t('other')} ${count}`,id=globalThis.crypto?.randomUUID?.()||`node-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,centerX=graphView.x+graphView.w/2-114,centerY=graphView.y+graphView.h/2-39;let x=at?at.x-92:centerX,y=at?at.y-36:centerY;if(!at){for(let k=0;k<160;k++){const r=65+30*Math.sqrt(k),a=k*2.399963,cx=centerX+Math.cos(a)*r,cy=centerY+Math.sin(a)*r,overlap=graph.nodes.some(n=>cx<n.x+258&&cx+228>n.x-30&&cy<n.y+108&&cy+78>n.y-30);if(!overlap){x=cx;y=cy;break}}}checkpoint();graph.nodes.push({id,name:label,type,x,y,value:'',source:'',sourceDate:'',confidence:'unverified',notes:''});selectedNode=id;selectedEdge=null;saveGraph();paint();inspector();updateStatus();$('#graphContext').hidden=true;toast(t('nodeAdded'))}
